                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 29, 14, 30, 0, TimeSpan.Zero), Description = "Picked up by carrier" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 30, 8, 15, 0, TimeSpan.Zero), Description = "Arrived at Chicago distribution center" },
            ]
        },
        ["PKG-002"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "Austin, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 30, 12, 0, 0, TimeSpan.FromHours(-5)),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 25, 10, 0, 0, TimeSpan.Zero), Description = "Order placed" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 26, 11, 0, 0, TimeSpan.Zero), Description = "Shipped from warehouse" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 28, 16, 45, 0, TimeSpan.Zero), Description = "Out for delivery" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 28, 18, 20, 0, TimeSpan.Zero), Description = "Delivered — signed by J. Smith" },
            ]
        },
        ["PKG-003"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 8, 17, 0, 0, TimeSpan.FromHours(-7)),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 1, 0, 30, 0, TimeSpan.Zero), Description = "Order placed" },
            ]
        },
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct = default)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger

@using sv_875fc27b0b04400880ee83331e875092.Client.Services

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h2>Shipment Tracker</h2>

@if (error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@error</p>
        <button class="btn btn-outline-danger" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    @if (isLoading)
    {
        <div class="alert alert-info" role="status">
            <p>Loading shipment <strong>@TrackingNumber</strong>…</p>
        </div>
    }
    else
    {
        <div class="alert alert-warning">
            <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
        </div>
    }
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    <div class="card mb-3">
        <div class="card-body">
            <h4 class="card-title">@shipment.TrackingNumber</h4>
            <p><strong>Status:</strong> @shipment.Status</p>
            <p><strong>Location:</strong> @shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("f")</p>
        </div>
    </div>

    <h5>Status Updates</h5>
    <ul class="list-group">
        @foreach (var update in shipment.Updates.OrderByDescending(u => u.Timestamp))
        {
            <li class="list-group-item">
                <strong>@update.Timestamp.ToString("g")</strong> — @update.Description
            </li>
        }
    </ul>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = default!;

    private CancellationTokenSource? cts;
    private string? loadedTrackingNumber;
    private ShipmentDetails? shipment;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(TrackingNumber, loadedTrackingNumber, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        loadedTrackingNumber = TrackingNumber;
        shipment = null;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cancellationToken);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (navigation away or parameter change) — let ComponentBase handle it.
            throw;
        }
        catch (OperationCanceledException ex)
        {
            Logger.LogWarning(ex, "Request timed out loading shipment {TrackingNumber}", TrackingNumber);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            error = "Something went wrong loading the shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

